-- Marking the Fallen (27845 and 27856) cannot be finished. The player uses the Banner of the Fallen (62517 and 62548,
-- spells 87293 and 87296) on 7 Fallen Marshtide Footmen (46881) or Fallen Stonard Warriors (46882), each of which gives
-- the credit (46909 and 46913) and disappears. Neither of the two creatures was spawned or scripted, and the banner
-- spells had no limit to their target. The corpses (28 and 31) lie on the battlefield of the invasion,
-- dead through the permanent feign death aura, and the banners work only on them.
-- Spawns, levels, flags, scripts and conditions are as in Legends of Azeroth 5.4.8.

UPDATE `creature_template` SET `minlevel` = 53, `maxlevel` = 54, `unit_flags` = 536870912, `AIName` = 'SmartAI' WHERE `entry` IN (46881, 46882) AND `ScriptName` = '';

DELETE FROM `creature_template_addon` WHERE `entry` IN (46881, 46882);

DELETE FROM `creature` WHERE `guid` BETWEEN 9310205 AND 9310263;

DELETE FROM `smart_scripts` WHERE `entryorguid` IN (46881, 46882) AND `source_type` = 0;

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` IN (87293, 87296);
